            main(()->{invoke(activity,"showPlaceCards");button("Media controls").performClick();});await(()->cardView(store,"media")!=null,"Media card was not placed");main(()->check(button(cardView(store,"media"),"Enable media access")!=null||hasText(cardView(store,"media"),"Nothing is playing"),"Media card fabricated playback or lost its access state"));
            main(()->{desktop.changePage(1);});await(()->store.page==1&&!(Boolean)field(desktop,"animating")&&cardView(store,"notes")==null,"Leaving the desktop retained the old card view");main(()->desktop.changePage(-1));await(()->store.page==0&&!(Boolean)field(desktop,"animating")&&cardView(store,"notes")!=null,"Returning did not recreate the desktop cards");
