            main(()->{model.set("shuffle_enabled",1);SceneRandomizer controller=(SceneRandomizer)field(activity,"sceneRandomizer");controller.sync(System.currentTimeMillis());store.preferences.edit().putLong("shuffle_due",System.currentTimeMillis()-1).apply();int before=store.mode;invoke(activity,"randomizeIfDue");check(store.mode==before,"Automatic shuffle ran over an open menu");invoke(activity,"closePanel");set(activity,"shuffleHomeAfter",0L);set(desktop,"lastInteraction",0L);set(activity,"powerSave",true);invoke(activity,"randomizeIfDue");check(store.mode==before,"Battery saving did not pause automatic shuffle");});
