    private LauncherStore.Item card(LauncherStore store,String type){for(LauncherStore.Item item:store.pages.get(store.page))if(item.key.equals("card:"+type))return item;return null;}
    private DesktopCardView cardView(LauncherStore store,String type){LauncherStore.Item item=card(store,type);return item==null?null:(DesktopCardView)find(v->("card:"+item.id).equals(v.getTag()));}
    private void drag(float x,float y,float dx,float dy,boolean hold){long start=SystemClock.uptimeMillis();pointer(start,MotionEvent.ACTION_DOWN,x,y);if(hold)SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+200);for(int n=1;n<=8;n++){pointer(start,MotionEvent.ACTION_MOVE,x+dx*n/8,y+dy*n/8);SystemClock.sleep(24);}pointer(start,MotionEvent.ACTION_UP,x+dx,y+dy);SystemClock.sleep(400);}
    private void pointer(long start,int action,float x,float y){MotionEvent event=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{check(test.getUiAutomation().injectInputEvent(event,true),"Touch injection failed");}finally{event.recycle();}}
    private Button button(String text){return button(activity.getWindow().getDecorView(),text);}private Button button(View root,String text){return (Button)find(root,v->v instanceof Button&&(text.contentEquals(((Button)v).getText())||text.contentEquals(Objects.toString(v.getContentDescription(),""))));}
    private boolean hasText(View root,String text){return root!=null&&find(root,v->v instanceof TextView&&((TextView)v).getText().toString().contains(text))!=null;}
    private View find(Predicate<View> predicate){return find(activity.getWindow().getDecorView(),predicate);}private View find(View root,Predicate<View> predicate){if(root==null||root.getVisibility()!=View.VISIBLE)return null;if(predicate.test(root))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View match=find(group.getChildAt(i),predicate);if(match!=null)return match;}}return null;}
    private void systemClick(String label){long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label))if(label.equalsIgnoreCase(Objects.toString(node.getText(),""))&&node.isEnabled()&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK))return;SystemClock.sleep(100);}throw new AssertionError("Dialog action missing: "+label);}
    private static JSONObject clone(JSONObject document)throws Exception{return new JSONObject(document.toString());}private void reject(JSONObject document,SettingsModel model){boolean rejected=false;try{new DesktopBackup.Prepared(document,model);}catch(Exception expected){rejected=true;}check(rejected,"Invalid desktop card record was accepted");}
    private Object field(Object object,String name){try{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception error){throw new AssertionError(error);}}
    private void set(Object object,String name,Object value){try{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);f.set(object,value);}catch(Exception error){throw new AssertionError(error);}}
    private void invoke(Object object,String name,Object... arguments){try{for(java.lang.reflect.Method method:object.getClass().getDeclaredMethods())if(method.getName().equals(name)&&method.getParameterCount()==arguments.length){method.setAccessible(true);method.invoke(object,arguments);return;}throw new NoSuchMethodException(name);}catch(Exception error){throw new AssertionError(error);}}
    private void main(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{task.run();}catch(Throwable failure){error.set(failure);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void await(BooleanSupplier ready,String message){long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){AtomicReference<Boolean> result=new AtomicReference<>(false);main(()->result.set(ready.getAsBoolean()));if(result.get())return;SystemClock.sleep(100);}throw new AssertionError(message);}
    private void capture(String name)throws Exception {SystemClock.sleep(1200);Bitmap image=test.getUiAutomation().takeScreenshot();check(image!=null,"Screenshot unavailable");File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    private void delete(File file){File[] children=file.listFiles();if(children!=null)for(File child:children)delete(child);file.delete();}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
